        min_c = min(c for r, c in component)
        max_c = max(c for r, c in component)

        color = 'B' if grid[min_r][min_c] == 'B' else 'c'
        blocks.append({
            'min_r': min_r, 'max_r': max_r,
            'min_c': min_c, 'max_c': max_c,
            'color': color,
            'cells': component
        })

    # Sort blocks by movement priority (front to back)
    if action == 'LEFT':
        blocks.sort(key=lambda b: b['min_c'])
    elif action == 'RIGHT':
        blocks.sort(key=lambda b: -b['max_c'])
    elif action == 'UP':
        blocks.sort(key=lambda b: b['min_r'])
    elif action == 'DOWN':
        blocks.sort(key=lambda b: -b['max_r'])

    # Check if a block can move (with chain reactions)
    def can_move(block, dr, dc, moved_map):
        if id(block) in moved_map:
            return moved_map[id(block)]
        nr = block['min_r'] + dr
        nc = block['min_c'] + dc
        height = block['max_r'] - block['min_r'] + 1
        width = block['max_c'] - block['min_c'] + 1
        if nr < 0 or nr + height > H or nc < 0 or nc + width > W:
            moved_map[id(block)] = False
            return False
        # Check destination cells
        for r in range(nr, nr + height):
            for c in range(nc, nc + width):
                if grid[r][c] == 'S':
                    moved_map[id(block)] = False
                    return False
                if grid[r][c] in ('B', 'c', 'W'):
                    # Check if it's part of this block
                    if (r, c) in block['cells']:
                        continue
                    # Find the block it belongs to
                    for other in blocks:
                        if (r, c) in other['cells']:
                            if not can_move(other, dr, dc, moved_map):
                                moved_map[id(block)] = False
                                return False
                            break
        moved_map[id(block)] = True
        return True

    # Compute final positions
    moved_map = {}
    final_positions = {}
    for block in blocks:
        if can_move(block, dr, dc, moved_map):
            final_positions[id(block)] = (block['min_r'] + dr, block['min_c'] + dc)
        else:
            final_positions[id(block)] = (block['min_r'], block['min_c'])

    # Apply moves
    new_grid = [['b'] * W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                new_grid[r][c] = 'S'
            elif grid[r][c] == 'Y':
                new_grid[r][c] = 'Y'
            elif grid[r][c] == 'B' and (r, c) not in block_cells:
                new_grid[r][c] = 'B'
            elif grid[r][c] == 'c' and (r, c) not in block_cells:
                new_grid[r][c] = 'c'

    for block in blocks:
        nr, nc = final_positions[id(block)]
        height = block['max_r'] - block['min_r'] + 1
        width = block['max_c'] - block['min_c'] + 1
        for dr2 in range(height):
            for dc2 in range(width):
                old_val = grid[block['min_r'] + dr2][block['min_c'] + dc2]
                new_grid[nr + dr2][nc + dc2] = old_val

    return [''.join(row) for row in new_grid]

